// ================== AYARLAR ==================
// Şifre/token değiştiğinde SADECE bu bloğu güncelleyin.
const AYARLAR = {
  // Bitrix24 gelen webhook (inbound) adresi, sonunda / olacak.
  // Örn: https://xre.bitrix24.com.tr/rest/1/abcdef123456/
  // Gerekli izinler: crm, user (user_brief yeterli)
  BITRIX_WEBHOOK_URL: 'https://BURAYA-PORTAL.bitrix24.com.tr/rest/1/BURAYA_WEBHOOK_KODU/',

  // Bitrix giden webhook (ONCRMLEAD*) kullanıyorsanız application_token.
  // Otomasyon kuralı (robot) ile tetikliyorsanız boş bırakın.
  BITRIX_APP_TOKEN: '',

  // "PROJELER SMS GELEN" statüsü
  HEDEF_STATU: 'UC_BVSKUN',

  // İlgilendiği proje bilgisinin tutulduğu lead alanı (örn. UF_CRM_1712345678).
  // Boşsa proje bilgisi lead başlığı/kaynak açıklamasından alınır.
  PROJE_ALANI: '',

  TELEGRAM_BOT_TOKEN: 'BURAYA_TELEGRAM_BOT_TOKEN',
  // Grup: https://web.telegram.org/k/#-5156472580
  // "chat not found" hatası alırsanız -1005156472580 deneyin (supergroup).
  TELEGRAM_CHAT_ID: '-5156472580',

  ERCCELL_URL: 'https://gateway.erccell.com.tr/corporatesms/sendsms/',
  ERCCELL_USERNAME: 'BURAYA_ERCCELL_KULLANICI_ADI',
  ERCCELL_PASSWORD: 'BURAYA_ERCCELL_SIFRE',
  ERCCELL_BASLIK: 'XRE',
  // true: 905XXXXXXXXX, false: 5XXXXXXXXX
  SMS_ULKE_KODU: true,
};
// ==============================================

const req = $input.first().json;
const body = req.body || {};
const query = req.query || {};

// Giden webhook token kontrolü (ayarlandıysa)
if (AYARLAR.BITRIX_APP_TOKEN) {
  const token = body?.auth?.application_token ?? body['auth[application_token]'];
  if (token !== AYARLAR.BITRIX_APP_TOKEN) return [];
}

// Lead ID'yi her olası formattan çek:
//  - Giden webhook (ONCRMLEADADD/UPDATE): data[FIELDS][ID]
//  - Otomasyon kuralı webhook'u: document_id[2] = "LEAD_123" veya ?lead_id={{ID}}
let leadId =
  body?.data?.FIELDS?.ID ?? body['data[FIELDS][ID]'] ??
  query.lead_id ?? query.id ?? body.lead_id ?? body.id;

if (!leadId) {
  const doc = body.document_id ?? query.document_id ?? body['document_id[2]'] ?? query['document_id[2]'];
  const ham = Array.isArray(doc) ? doc[2] : (doc && typeof doc === 'object' ? doc[2] : doc);
  const m = String(ham ?? '').match(/(\d+)\s*$/);
  if (m) leadId = m[1];
}

if (!leadId || !/^\d+$/.test(String(leadId).trim())) return [];

const webhook = AYARLAR.BITRIX_WEBHOOK_URL.replace(/\/?$/, '/');
return [{
  json: {
    ...AYARLAR,
    BITRIX_WEBHOOK_URL: webhook,
    BITRIX_PORTAL_URL: new URL(webhook).origin,
    lead_id: String(leadId).trim(),
  },
}];

const cfg = $('Ayarlar ve Lead ID').first().json;
const lead = $input.first().json.result;

// Sadece "PROJELER SMS GELEN" statüsündeki lead'ler
if (!lead || lead.STATUS_ID !== cfg.HEDEF_STATU) return [];

// Aynı lead için ikinci kez SMS/bildirim gitmesin
const store = $getWorkflowStaticData('global');
store.islenenler = store.islenenler || {};
const simdi = Date.now();
for (const [id, t] of Object.entries(store.islenenler)) {
  if (simdi - t > 90 * 24 * 3600 * 1000) delete store.islenenler[id];
}
if (store.islenenler[lead.ID]) return [];
store.islenenler[lead.ID] = simdi;

const temizle = (s) => String(s ?? '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/\[\/?[a-z]+[^\]]*\]/gi, '')
  .replace(/&nbsp;/g, ' ')
  .trim();

const full_name =
  [lead.NAME, lead.SECOND_NAME, lead.LAST_NAME].map(s => (s || '').trim()).filter(Boolean).join(' ') ||
  temizle(lead.TITLE) || 'Değerli Müşterimiz';

const hamTel = (lead.PHONE || []).map(p => p.VALUE).find(Boolean) || '';
let on = String(hamTel).replace(/\D/g, '');
if (on.startsWith('0090')) on = on.slice(4);
else if (on.startsWith('90') && on.length === 12) on = on.slice(2);
else if (on.startsWith('0') && on.length === 11) on = on.slice(1);
const telGecerli = /^5\d{9}$/.test(on);
const sms_phone = telGecerli ? (cfg.SMS_ULKE_KODU ? '90' + on : on) : '';
const phone = telGecerli ? '+90' + on : (hamTel || '-');

const email = (lead.EMAIL || []).map(e => e.VALUE).find(Boolean) || '-';

let proje = '';
if (cfg.PROJE_ALANI) {
  const v = lead[cfg.PROJE_ALANI];
  proje = Array.isArray(v) ? v.join(', ') : temizle(v);
}

const tarihKaynak = lead.DATE_CREATE ? new Date(lead.DATE_CREATE) : new Date();
const tarih = tarihKaynak.toLocaleString('tr-TR', {
  timeZone: 'Europe/Istanbul',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

return [{
  json: {
    lead_id: lead.ID,
    full_name,
    phone,
    sms_phone,
    email,
    form_adi: temizle(lead.SOURCE_DESCRIPTION) || temizle(lead.TITLE) || 'XRE Project Bilgi Formu',
    proje: proje || temizle(lead.TITLE) || '-',
    cevap: temizle(lead.COMMENTS) || '-',
    tarih,
    assigned_id: lead.ASSIGNED_BY_ID || '',
    bitrix_link: cfg.BITRIX_PORTAL_URL + '/crm/lead/details/' + lead.ID + '/',
  },
}];

const cfg = $('Ayarlar ve Lead ID').first().json;
const b = $('Başvuruyu Hazırla').first().json;
const u = ($input.first().json.result || [])[0];

const sorumlu = u
  ? [u.NAME, u.LAST_NAME].filter(Boolean).join(' ') || u.EMAIL || ('#' + b.assigned_id)
  : (b.assigned_id ? '#' + b.assigned_id : '-');

const sms_mesaj =
  'Merhaba ' + b.full_name + ', XRE Project başvurunuz alınmıştır. ' +
  'Proje satış temsilcimiz sizinle en kısa sürede iletişime geçecektir. ' +
  "XRE'li günler dileriz. https://xre.com.tr/";

const cdata = (s) => '<![CDATA[' + String(s).replace(/]]>/g, ']]]]><![CDATA[>') + ']]>';
const xmlEsc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const sms_xml =
`<?xml version="1.0" encoding="UTF-8"?>
<CORPORATESMS>
    <HEADER>
        <USERNAME>${xmlEsc(cfg.ERCCELL_USERNAME)}</USERNAME>
        <PASSWORD>${xmlEsc(cfg.ERCCELL_PASSWORD)}</PASSWORD>
        <SMSHEADER>${cdata(cfg.ERCCELL_BASLIK)}</SMSHEADER>
        <SMSTYPE>UC</SMSTYPE>
        <SENDTYPE>1:N</SENDTYPE>
    </HEADER>
    <SMS>
        <SMS_MESSAGE>${cdata(sms_mesaj)}</SMS_MESSAGE>
        <NUMBERS>${b.sms_phone}</NUMBERS>
    </SMS>
</CORPORATESMS>`;

return [{ json: { ...b, sorumlu, sms_mesaj, sms_xml } }];

const m = $('Mesajları Hazırla').first().json;
const r = $input.first().json;

let basarili = false;
let detay = '';

if (!m.sms_phone) {
  detay = 'Geçerli cep telefonu numarası yok (' + m.phone + ')';
} else if (r.error) {
  detay = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
} else {
  const yanit = String(r.data ?? JSON.stringify(r)).trim();
  detay = yanit.slice(0, 500);
  basarili = !/(hata|error|fail|invalid|ge[cç]ersiz|yetkisiz|unauthori|denied|ba[sş]ar[iı]s[iı]z)/i.test(yanit);
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const telegram_text = [
  '🔔 <b>Yeni Form Başvurusu</b>',
  '',
  '👨‍💼 Atanan: ' + esc(m.sorumlu),
  '📋 Doldurulan form: ' + esc(m.form_adi),
  '🏢 İlgilendiği proje: ' + esc(m.proje),
  '👤 Ad Soyad: ' + esc(m.full_name),
  '📞 Telefon: ' + esc(m.phone),
  '✉️ E-posta: ' + esc(m.email),
  '📝 Cevap: ' + esc(m.cevap),
  '🕒 Tarih: ' + esc(m.tarih),
  '📨 SMS: ' + (basarili ? 'Gönderildi ✅' : 'Gönderilemedi ❌'),
  '🔗 <a href="' + esc(m.bitrix_link) + '">Bitrix\'te aç (#' + esc(m.lead_id) + ')</a>',
].join('\n');

const simdi = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });
const bitrix_yorum = basarili
  ? '✅ SMS GÖNDERİLDİ\nTarih: ' + simdi + '\nNumara: ' + m.phone + '\nMesaj: ' + m.sms_mesaj + '\nErccell yanıtı: ' + detay
  : '❌ SMS GÖNDERİLEMEDİ\nTarih: ' + simdi + '\nNumara: ' + m.phone + '\nSebep: ' + detay;

return [{ json: { lead_id: m.lead_id, sms_basarili: basarili, sms_detay: detay, telegram_text, bitrix_yorum } }];
